1686	 *   Callers that need to combine full-text search with tag filtering should post-process
1687	 *   the returned array. This constraint was not addressed in WP-004 or WP-005 and remains
1688	 *   open for a future work package.
1689	 */
1690	export async function handleListKnowledge(
1691	  ledgerRoot: string,
1692	  params: KnowledgeListParams = {}
1693	): Promise<Insight[]> {
1694	  const manager = new KnowledgeStoreManager(ledgerRoot);
1695	
1696	  // Validate scope — unrecognised values fall back to undefined (no filter).
1697	  const scopeResult = InsightScope.safeParse(params.scope);
1698	  const scope = scopeResult.success ? scopeResult.data : undefined;
1699	
1700	  const category = params.category ?? undefined;
1701	  const project_slug = params.project_slug ?? undefined;
1702	
1703	  // Split comma-separated tags; ignore empty segments.
1704	  const tags =
1705	    params.tags && params.tags.trim().length > 0
1706	      ? params.tags
1707	          .split(',')
1708	          .map((t) => t.trim())
1709	          .filter((t) => t.length > 0)
1710	      : undefined;
1711	
1712	  // Coerce pagination params.
1713	  const limitRaw = params.limit !== undefined ? Math.floor(Number(params.limit)) : NaN;
1714	  const limit = !isNaN(limitRaw) && limitRaw > 0 ? limitRaw : undefined;
1715	
1716	  const offsetRaw = params.offset !== undefined ? Math.floor(Number(params.offset)) : NaN;
1717	  const offset = !isNaN(offsetRaw) && offsetRaw >= 0 ? offsetRaw : 0;
1718	
1719	  if (params.query && params.query.trim().length > 0) {
1720	    return manager.searchInsights(params.query.trim(), { scope, project_slug, category });
1721	  }
1722	
1723	  return manager.listInsights({ scope, category, tags, project_slug, limit, offset });
1724	}
