1727	// PATCH /api/knowledge/:id
1728	// ---------------------------------------------------------------------------
1729	
1730	/**
1731	 * Updates an existing knowledge insight identified by its numeric ID.
1732	 *
1733	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
1734	 * for non-integer, zero, or floating-point strings). Validates the request body
1735	 * via `KnowledgeUpdateBodySchema` (throws VALIDATION_ERROR for unknown fields or
1736	 * type mismatches). Extracts `scope` and `project_slug` discriminator fields to
1737	 * scope the update to the correct store.
1738	 *
1739	 * `superseded_by: null` in the body is mapped to `undefined` so the field is
1740	 * cleared (removed) on the stored insight.
1741	 *
1742	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
1743	 *
1744	 * @param ledgerRoot  Absolute path to the central ledger root.
1745	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
1746	 * @param body        Parsed request body (any shape — validated here).
1747	 * @returns The updated Insight.
1748	 */
1749	export async function handleUpdateKnowledge(
1750	  ledgerRoot: string,
1751	  rawId: string,
1752	  body: unknown
1753	): Promise<Insight> {
1754	  const id = parseKnowledgeId(rawId);
1755	
1756	  const parseResult = KnowledgeUpdateBodySchema.safeParse(body);
1757	  if (!parseResult.success) {
1758	    validationError('Invalid knowledge update body.', parseResult.error.issues);
1759	  }
1760	
1761	  const { scope, project_slug, superseded_by, ...rest } = parseResult.data;
1762	
1763	  // Map superseded_by: null → undefined so the field is cleared on the stored insight.
1764	  const updates: Parameters<KnowledgeStoreManager['updateInsight']>[1] = {
1765	    ...rest,
1766	    ...(superseded_by === null ? { superseded_by: undefined } : superseded_by !== undefined ? { superseded_by } : {}),
1767	  };
1768	
1769	  const manager = new KnowledgeStoreManager(ledgerRoot);
1770	
1771	  try {
1772	    return await manager.updateInsight(id, updates, { scope, project_slug });
1773	  } catch (err) {
1774	    const msg = err instanceof Error ? err.message : String(err);
1775	    if (msg.includes('not found')) {
1776	      throw new ApiError('NOT_FOUND', 'Insight not found.');
1777	    }
1778	    throw err;
1779	  }
1780	}
