1786	/**
1787	 * Deletes an existing knowledge insight identified by its numeric ID.
1788	 *
1789	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
1790	 * for non-integer, zero, or floating-point strings). Requires `scope` as a
1791	 * query parameter; when `scope === 'project'`, `project_slug` is also required
1792	 * (throws VALIDATION_ERROR if absent). Scopes the deletion to the correct store
1793	 * to prevent accidental cross-scope deletion when the same numeric ID exists in
1794	 * multiple stores.
1795	 *
1796	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
1797	 *
1798	 * @param ledgerRoot   Absolute path to the central ledger root.
1799	 * @param rawId        Raw ID string from the URL parameter (e.g. "42").
1800	 * @param scope        Required scope query parameter ('global' or 'project').
1801	 * @param project_slug Required when scope is 'project'; the project slug.
1802	 * @returns `null` — consistent with other delete handlers.
1803	 */
1804	export async function handleDeleteKnowledge(
1805	  ledgerRoot: string,
1806	  rawId: string,
1807	  scope: string | undefined,
1808	  project_slug?: string
1809	): Promise<null> {
1810	  const id = parseKnowledgeId(rawId);
1811	
1812	  // Validate scope — required and must be a recognised InsightScope value.
1813	  const scopeResult = InsightScope.safeParse(scope);
1814	  if (!scopeResult.success) {
1815	    validationError('scope query parameter is required and must be "global" or "project".');
1816	  }
1817	  const validatedScope = scopeResult.data;
1818	
1819	  // project_slug is required when scope === 'project'.
1820	  if (validatedScope === 'project' && !project_slug) {
1821	    validationError('project_slug query parameter is required when scope is "project".');
1822	  }
1823	
1824	  const manager = new KnowledgeStoreManager(ledgerRoot);
1825	
1826	  try {
1827	    await manager.deleteInsight(id, { scope: validatedScope, project_slug });
1828	  } catch (err) {
1829	    const msg = err instanceof Error ? err.message : String(err);
1830	    if (msg.includes('not found')) {
1831	      throw new ApiError('NOT_FOUND', 'Insight not found.');
1832	    }
1833	    throw err;
1834	  }
1835	
1836	  return null;
