1839	// ---------------------------------------------------------------------------
1840	// POST /api/knowledge/:id/promote
1841	// ---------------------------------------------------------------------------
1842	
1843	/**
1844	 * Promotes a project-scoped insight to global scope.
1845	 *
1846	 * Uses add-first-then-delete ordering: adds the insight to the global store
1847	 * before deleting the original project-scoped entry. This ensures that a
1848	 * failure during deletion leaves the insight in both scopes (a detectable
1849	 * duplicate) rather than silently losing it.
1850	 *
1851	 * The returned insight is the newly created global-scoped copy — it has a
1852	 * **different numeric ID** than the original (assigned by the global store's
1853	 * `next_id` counter). The frontend must match by pre-promote ID, not the new ID.
1854	 *
1855	 * @param ledgerRoot  Absolute path to the central ledger root.
1856	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
1857	 * @param scope       Source scope — must be "project" (global insights cannot be promoted).
1858	 * @param project_slug Required when scope is "project"; the source project slug.
1859	 * @returns The newly created global Insight.
1860	 * @throws ApiError VALIDATION_ERROR if scope is not "project", or insight is already global.
1861	 * @throws ApiError NOT_FOUND if no matching insight exists in the specified scope.
1862	 */
1863	export async function handlePromoteKnowledge(
1864	  ledgerRoot: string,
1865	  rawId: string,
1866	  scope: string | undefined,
1867	  project_slug?: string
1868	): Promise<Insight> {
1869	  const id = parseKnowledgeId(rawId);
1870	
1871	  // Validate scope — must be 'project' (global insights are already global).
1872	  const scopeResult = InsightScope.safeParse(scope);
1873	  if (!scopeResult.success) {
1874	    validationError('scope query parameter is required and must be "global" or "project".');
1875	  }
1876	  const validatedScope = scopeResult.data;
1877	
1878	  if (validatedScope === 'global') {
1879	    validationError('Insight is already global and cannot be promoted.');
1880	  }
1881	
1882	  // project_slug is required when scope === 'project'.
1883	  if (!project_slug) {
1884	    validationError('project_slug query parameter is required when scope is "project".');
1885	  }

1886	
1887	  const manager = new KnowledgeStoreManager(ledgerRoot);
1888	
1889	  // Locate the source insight — throws NOT_FOUND if absent or out-of-scope.
1890	  const source = await findInsightById(manager, id, {
1891	    scope: validatedScope,
1892	    project_slug,
1893	  });
1894	
1895	  // Add-first: create the global copy before deleting the original.
1896	  // eslint-disable-next-line @typescript-eslint/no-unused-vars
1897	  const { id: _sourceId, project_slug: _slug, ...sourceFields } = source;
1898	  const newInsight = await manager.addInsight({
1899	    ...sourceFields,
1900	    scope: 'global',
1901	    project_slug: undefined,
1902	  });
1903	
1904	  // Delete-after: remove the original project-scoped entry.
1905	  try {
1906	    await manager.deleteInsight(id, { scope: validatedScope, project_slug });
1907	  } catch (err) {
1908	    // If deletion fails, the insight exists in both scopes (detectable duplicate).
1909	    // Surface the error so the caller is aware — do not silently swallow it.
1910	    const msg = err instanceof Error ? err.message : String(err);
1911	    if (msg.includes('not found')) {
1912	      throw new ApiError('NOT_FOUND', 'Insight not found during post-promote deletion.');
1913	    }
1914	    throw err;
1915	  }
1916	
1917	  return newInsight;
1918	}
