1924	/**
1925	 * Zod schema for the POST /api/knowledge/:id/move request body.
1926	 *
1927	 * Fields validated by the Zod schema (format/type constraints):
1928	 * - `source_scope`        — "global" or "project" (InsightScope enum)
1929	 * - `source_project_slug` — optional in the schema (`z.string().regex(PROJECT_SLUG_REGEX).optional()`);
1930	 *                           the conditional-required constraint (required when source_scope is "project")
1931	 *                           is enforced in handler logic, not here.
1932	 * - `project_slug`        — destination project slug (required; must match PROJECT_SLUG_REGEX)
1933	 *
1934	 * Note: `source_project_slug` is `.optional()` at the Zod layer so that the schema can parse
1935	 * a body that omits it — the handler then checks the combination of `source_scope` and
1936	 * `source_project_slug` and throws VALIDATION_ERROR if the conditional constraint is violated.
1937	 * This is consistent with how other conditional-required fields are handled across this API.
1938	 */
1939	export const KnowledgeMoveBodySchema = z
1940	  .object({
1941	    source_scope: InsightScope,
1942	    source_project_slug: z.string().regex(PROJECT_SLUG_REGEX).optional(),
1943	    project_slug: z.string().regex(PROJECT_SLUG_REGEX),
1944	  })
1945	  .strict();
